<template><view class="order-card" @tap="$emit('select')"><view class="head"><text class="number">订单号 {{order.orderNo || order.id}}</text><ui-status-tag :label="statusLabel" :tone="statusTone"/></view><view class="goods"><image :src="order.product.image" mode="aspectFill"/><view class="copy"><text class="name">{{order.product.name}}</text><text class="sku">{{order.sku.name}} × {{order.qty}}</text><text class="price">¥{{Number(order.total).toFixed(2)}}</text></view><ui-icon class="detail-arrow" name="chevron-right" :size="28"/></view><view v-if="$slots.actions" class="actions"><slot name="actions"/></view></view></template>
<script>export default{emits:['select'],props:{order:{type:Object,required:true}},computed:{statusLabel(){return({unpaid:'待付款',pending:'待接单',accepted:'已接单',serving:'服务中',refunding:'退款中',completed:'已完成',refunded:'退款/售后',cancelled:'已取消'})[this.order.status]||this.order.status},statusTone(){return({unpaid:'warning',pending:'brand',accepted:'success',serving:'warning',refunding:'danger',completed:'neutral',refunded:'danger',cancelled:'neutral'})[this.order.status]||'neutral'}}}</script>
<style scoped>.order-card{margin-bottom:18rpx;padding:24rpx;border-radius:24rpx;background:var(--surface);box-shadow:var(--shadow-card)}.head{display:flex;align-items:center;justify-content:space-between;padding-bottom:20rpx;border-bottom:1rpx solid var(--line)}.number{color:var(--muted);font-size:22rpx}.goods{display:flex;align-items:center;gap:20rpx;padding:22rpx 0}.goods image{width:142rpx;height:142rpx;border-radius:16rpx;background:var(--surface-soft)}.copy{min-width:0;flex:1;display:flex;flex-direction:column;gap:12rpx}.name{font-size:27rpx;font-weight:700}.sku{color:var(--muted);font-size:23rpx}.price{margin-top:auto;color:var(--primary);font-weight:800}.detail-arrow{flex-shrink:0;color:var(--muted)}.actions{display:flex;justify-content:flex-end;gap:16rpx;padding-top:18rpx;border-top:1rpx solid var(--line)}</style>
